// layout.min.js
import { clearSession } from "../js/utils/errors.js";
import { IndexedDBStorage } from "./adapters/IndexedDBStorage.js";
import { ApiAdmin } from "./api/ApiAdmin.js";
import { ApiUser } from "./api/ApiUser.js";

let redirecting = !1;
export const GLOBAL_DEBUG = localStorage.getItem("debugMode") === "true";
const API_BASE = import.meta.env?.VITE_API_URL || "https://localhost:5000";
const storage = new IndexedDBStorage("AuthDB", "tokens");
const api_admin = new ApiAdmin({ baseURL: API_BASE, storage, debugEnabled: GLOBAL_DEBUG });
const api_user = new ApiUser({ baseURL: API_BASE, storage, debugEnabled: GLOBAL_DEBUG });

document.addEventListener("DOMContentLoaded", async () => {
    initSidebarToggle();
    await handleUrlAlerts();
    initGlobalEvents();
    initDebugPanel();
    initDebugConsole();
});

async function handleUrlAlerts() {
    try {
        const p = new URLSearchParams(globalThis.location.search);
        const a = {
            logout: { m: "⚠️ Tu sesión ha expirado. Por favor, iniciá sesión nuevamente.", t: "warning", c: !0 },
            unauthorized: { m: "🚫 Acceso no autorizado. Iniciá sesión para continuar.", t: "danger" },
            untoken: { m: "🚫 No existe token válido.", t: "danger" }
        };
        let tr = !1;
        for (const [k, v] of Object.entries(a))
            if (p.get(k) === "true") {
                showGlobalAlert(v.m, v.t, 6e3);
                if (v.c) await clearSession();
                tr = !0;
            }
        if (tr && !globalThis._historyReplaced && globalThis.isSecureContext)
            if (globalThis.history?.replaceState) {
                globalThis._historyReplaced = !0;
                globalThis.history.replaceState({}, document.title, globalThis.location.pathname);
            }
    } catch (e) {
        console.warn("⚠️ handleUrlAlerts error:", e.message);
    }
}

function initSidebarToggle() {
    const s = document.getElementById("sidebar"),
        m = document.getElementById("mainContent"),
        t = document.getElementById("sidebarToggle");
    if (!s || !m || !t) return;
    t.addEventListener("click", () => {
        s.classList.toggle("collapsed");
        s.classList.toggle("show");
        m.classList.toggle("expanded");
    });
    const r = () => {
        const n = globalThis.innerWidth < 992;
        s.classList.toggle("collapsed", n);
        m.classList.toggle("expanded", n);
    };
    globalThis.addEventListener("resize", r);
    r();
}

export function showGlobalAlert(m, t = "info", d = 4e3) {
    const c = document.getElementById("globalAlerts") || document.getElementById("alertContainer");
    if (!c) return console.warn("⚠️ No se encontró contenedor de alertas.");
    const w = document.createElement("div");
    w.className = `alert alert-${t} alert-dismissible fade show shadow mt-2`;
    w.setAttribute("role", "alert");
    w.setAttribute("aria-live", "assertive");
    w.setAttribute("aria-atomic", "true");
    w.innerHTML = `<div>${m}</div><button type="button" class="btn-close" data-bs-dismiss="alert" aria-label="Close"></button>`;
    c.appendChild(w);
    if (d) setTimeout(() => { w.classList.remove("show"); setTimeout(() => w.remove(), 300); }, d);
}

function initGlobalEvents() {
    document.addEventListener("userLoggedOut", async () => {
        if (redirecting) return;
        redirecting = !0;
        await clearSession();
        showGlobalAlert("👋 Sesión finalizada correctamente.", "info");
        setTimeout(() => (globalThis.location.href = "/"), 1200);
    });
    document.addEventListener("debug:log", e => {
        const { label, args, level = "info" } = e.detail,
            c = { info: "#0dcaf0", success: "#28a745", warn: "#ffc107", error: "#dc3545", debug: "#6f42c1" }[level] || "#aaa";
        console.log(`%c[${level.toUpperCase()}] ${label}`, `color:${c}`, ...args);
    });
    document.addEventListener("session:change", e => {
        const { loggedIn, role } = e.detail;
        showGlobalAlert(
            loggedIn ? `✅ Sesión activa como ${role.toUpperCase()}` : "🚪 Sesión cerrada.",
            loggedIn ? "success" : "warning",
            4e3
        );
    });
    document.addEventListener("metrics:event", e => {
        const { event, role, username } = e.detail;
        console.info(`📊 Evento de métrica → ${event} (${role || "?"})`, username);
    });
}

export function initDebugPanel() {
    const t = document.getElementById("debugToggle");
    if (!t) return;
    const s = localStorage.getItem("debugMode") === "true";
    t.checked = s;
    setGlobalDebug(s);
    t.addEventListener("change", e => {
        const en = e.target.checked;
        localStorage.setItem("debugMode", en);
        setGlobalDebug(en);
    });
}

function setGlobalDebug(en) {
    api_user.debugEnabled = en;
    api_admin.debugEnabled = en;
    if (globalThis.AuthAppInstance) globalThis.AuthAppInstance.debugEnabled = en;
    console.info(`%c🪲 Debug Mode ${en ? "ACTIVADO" : "DESACTIVADO"}`, `color:${en ? "#00e676" : "#ff5252"};font-weight:bold;`);
}

function initDebugConsole() {
    const t = document.getElementById("debugToggle"),
        c = document.getElementById("debugConsole"),
        o = document.getElementById("debugOutput"),
        b = document.getElementById("clearDebug");
    if (!t || !c) return;
    t.addEventListener("change", e => c.classList.toggle("hidden", !e.target.checked));
    b.addEventListener("click", () => (o.innerHTML = ""));
    document.addEventListener("debug:log", e => {
        const { label, args } = e.detail,
            time = new Date().toLocaleTimeString(),
            l = document.createElement("div");
        l.className = "debug-log";
        l.innerHTML = `<time>[${time}]</time> ${label}: ${args.map(a => JSON.stringify(a, null, 2)).join(" ")}`;
        o.appendChild(l);
        o.scrollTop = o.scrollHeight;
    });
}
